// Healthy scans may take longer than the deletion allowance. Inventory stays
// excluded, yields to the event loop, and reaches a complete safety proof.
for(const slowDirectory of ['checkpoints','objects']){
  const t=harness();await t.controller.install();await t.controller.connect();const directory=await nested(t.directory,REPO,slowDirectory),objects=await nested(t.directory,REPO,'objects');
  for(let i=0;i<40;i++)await writeLegacyFile(directory,'ordinary-'+i+'.txt');const orphan='obj_'+'d'.repeat(32)+'.sdobject';await writeLegacyFile(objects,orphan);
  t.directory.permission='prompt';await t.controller.refreshPermission();await t.clock.advance(72*3600000);
  // Permission refresh establishes history before the background inventory.
  t.directory.permission='granted';await t.controller.refreshPermission();const base=directory.entries.bind(directory);let visited=0;
  directory.entries=async function*(){for await(const pair of base()){await t.clock.advance(1000);visited++;yield pair;}};
  t.maintenanceStore.value={requestedAt:new Date(t.clock.now()).toISOString(),nextEligibleAt:new Date(t.clock.now()).toISOString(),reason:'repository-state'};
  await t.controller.refreshPermission();t.controller.syncOwnership();await t.clock.advance(1000);await drain();await settleMaintenance(t);
  assert.ok(visited>40,'the finite inventory must progress past the former repeated prefix: '+JSON.stringify({slowDirectory,visited,maintenance:t.controller.diagnosticMaintenance(),captures:t.captures}));assert.equal(objects.names().includes(orphan),false,'complete responsive inventory must reach safe GC');assert.equal(t.maintenancePending(),false);assert.equal(t.controller.diagnosticMaintenance().lastOutcome,'completed');
  assert.equal(objects.names().some(name=>name.endsWith('.sdmaintenance')),false,'successful inventory must release its renewed exclusion marker');
}
